import json,pathlib
R=pathlib.Path(__file__).resolve().parents[1];concepts=[]
def c(id,name,definition,caveat,uses):
 concepts.append(dict(id=id,name=name,definition=definition,caveat=caveat,uses=[dict(paper=p,role=r,source=dict(page=n,label=s)) for p,r,n,s in uses]))
c('flow','Flow matching','Learn a time-dependent velocity field by matching target velocities along a chosen path. At inference, integrate the learned field to transport an initial state.','The starting state and meaning of time differ across these papers. A shared learning family does not imply the same task.', [('pdf','Separate morphology and intensity evolution for disease forecasting.',8,'Sec. 3.2'),('drift','Learn residual transport from a coarse APN image to an HR target.',7,'Sec. 3.4'),('paraflow','Keep a pretrained field fixed; change how its ODE is solved.',3,'Sec. 4')])
c('rectified','Rectified flow','The DRIFT training path interpolates linearly between a coarse estimate and the target, with target velocity equal to their difference.','A straight training interpolation does not make a learned numerical inference trajectory exact in one step.', [('drift','Residual image refinement after anatomical projection.',7,'Eq. 6'),('paraflow','Related flow-model background; the contribution is a solver, not rectified-flow training.',2,'Sec. 2')])
c('ode','ODE sampling','Numerically integrate a neural velocity field over a time interval to obtain a terminal state. Each solver evaluation calls the field model.','A solver step, a sequential iteration, and a total network evaluation need not be the same quantity.', [('drift','Thickness chooses the number of Euler refinements.',9,'Sec. 3.6'),('paraflow','Tentative states at multiple schedule times are evaluated concurrently.',4,'Algorithm 1'),('pdf','Integrate morphology and intensity fields in a forecasting pipeline.',9,'Inference')])
c('nfe','NFE','Number of function evaluations: how many times a neural vector field is evaluated.','ParaFlow reports total NFEs across parallel evaluations. DRIFT’s velocity NFEs exclude APN and preprocessing.', [('paraflow','Total workload can increase while sequential iterations decrease.',5,'Definition of NFE'),('drift','AIS allocates 0–15 velocity-network evaluations in the main setting.',9,'Sec. 3.6')])
c('parallel','Parallel fixed-point iteration','Update multiple trajectory guesses using vector-field evaluations from the previous iteration, then repeat until a convergence criterion is met.','Parallel evaluations require hardware and memory; the theoretical bound alone does not guarantee a wall-clock speedup.', [('paraflow','Triangular trajectory equations solved in a sliding window.',4,'Secs. 4.3–4.4')])
c('diffusion','Diffusion / generative modeling','These papers use or study existing image generators that iteratively transform a latent or token state into an image. Their exact generation objectives vary.','Do not equate every image-generation architecture with the same diffusion or flow formulation.', [('transferability','Studies discrete/continuous diffusion and autoregressive UMM families.',3,'Sec. 2.1'),('debat','LightningDiT learns the concatenated frequency-aware latent distribution.',9,'Sec. 3.3'),('paraflow','Evaluates flow-matching models SD3 and FLUX.',4,'Experimental setup')])
c('wavelets','Haar DWT','A fixed discrete wavelet transform separates coarse information from directional detail bands. In 2D there is one LL and three detail bands; in 3D one LLL and seven detail bands per level.','The same transform plays different roles: learned representation in DeBaT versus training augmentation in KernelWave.', [('debat','Split 2D image bands before training separate encoders and decoders.',8,'Sec. 3.2'),('wcc4ms','Scale 3D detail coefficients to make smooth/sharp training images.',6,'Sec. 3.2')])
c('frequency','Frequency / high-frequency detail','High spatial frequencies describe rapid spatial variations such as fine textures and boundaries. Low frequencies describe more slowly varying structure.','High frequency is not synonymous with useful anatomy: it can also include noise. Frequency processing here includes Haar, FFT, DoG, and bandwidth reasoning.', [('debat','Protect fine details inside the tokenizer.',8,'Sec. 3.2'),('wcc4ms','Approximate CT reconstruction-related frequency shifts.',6,'Sec. 3.2'),('sphere','Use FFT features and k-space simulation to derive a prior.',6,'Secs. 3.1–3.2'),('drift','Model thickness-related loss of through-plane bandwidth.',9,'Eq. 13'),('pdf','Use Difference-of-Gaussians lesion-texture guidance at inference.',22,'Appendix D')])
c('latent','Latent representation','An encoded representation used between image input/output and the model’s central computation. Its structure controls what information can be carried forward.','A shared representation is not automatically a better compressed representation; the papers measure different outcomes.', [('debat','Concatenate separate low/high learned codes at a matched total size.',9,'Sec. 3.3'),('transferability','Probe how unified versus separate visual representations affect transfer.',5,'Fig. 1'),('paraflow','Samples the existing model state without redesigning its representation.',4,'Experimental setup')])
c('mri','MRI','Magnetic resonance images are the medical inputs or outputs of several papers in this collection. The tasks concern different stages of the imaging workflow.','Shared modality does not imply shared output: masks, super-resolved scans, and future scans answer different questions.', [('sphere','Segment tumors in reconstructed brain MRI.',1,'Abstract'),('drift','Reconstruct finer through-plane resolution.',5,'Sec. 3'),('pdf','Forecast future brain images and lesion progression.',9,'Inference')])
c('kspace','k-space sampling','MRI measurements encode spatial frequencies. A sampling operator selects which measurements contribute to a reconstructed image.','This is acquisition sampling, not generative sampling. SPHERE estimates sampling-related parameters from already reconstructed images.', [('sphere','Predict parameters, simulate perturbations, then derive a structural prior.',7,'Eqs. 10–14')])
c('dvf','Deformation vector field','A spatial field that assigns a displacement vector to each location, allowing one image or feature grid to be warped toward another.','SPHERE’s field is an acquisition-related structural proxy; PDF’s warp comes from predicted lesion evolution.', [('sphere','Guide feature alignment and retention with a sampling-induced proxy.',8,'Sec. 3.3'),('pdf','Estimate dense optical-flow displacement between lesion masks.',9,'Eq. 20')])
c('thickness','Slice thickness / PAD','Slice thickness controls through-plane signal integration. DRIFT uses 1 − target thickness / input thickness as a normalized bandwidth-deficit cue.','PAD is metadata-based severity, not a learned per-image difficulty score.', [('drift','Condition both stages and set the AIS refinement budget.',9,'Eqs. 13–14')])
c('physics','Physics-informed learning','Use structure motivated by an acquisition mechanism or disease-dynamics model to guide a learned method.','A physics-inspired proxy or soft regularizer does not establish exact physical or biological fidelity.', [('sphere','Sampling-related DVF guides segmentation.',7,'Sec. 3.2'),('pdf','Diffusion–reaction–advection span constrains morphology velocity.',7,'Eq. 13'),('drift','SLR slice-profile simulation and thickness-based bandwidth cue.',6,'Sec. 3.1; p. 9 Sec. 3.6')])
c('fisher','Fisher-KPP','A reaction–diffusion formulation combines spatial spread with a logistic local-growth term. PDF adds advection to account for transport.','PDF constructs a normalized concentration proxy from lesion masks; it does not measure biological cell density.', [('pdf','Provides the components for a physics-inspired span.',5,'Eqs. 1–2')])
c('pde','PDE regularization','In PDF, project the morphology velocity onto a span of spatial diffusion, reaction and advection components; penalize the squared residual.','The loss is soft. It does not embed an exact PDE solver in the inference process.', [('pdf','Regularizes morphology training alongside the flow-matching objective.',7,'Eq. 13')])
c('segmentation','Medical segmentation','Predict a region mask identifying the anatomy or pathology of interest.','The scope differs: brain MRI, universal 2D medical tasks, and candidate-centered 3D tumors are not interchangeable benchmarks.', [('sphere','Brain tumor masks informed by an MRI acquisition prior.',5,'Fig. 3'),('c2p','Prompt-free foreground/background masks across modalities.',5,'Fig. 2'),('wcc4ms','3D tumor masks from localized candidate patches.',9,'Sec. 4.2')])
c('generalization','Cross-domain generalization','Evaluate whether a trained model works on a different dataset, acquisition condition, or modality without simply retraining on that test domain.','Different papers use different protocols. Do not rank robustness from scores on unrelated datasets.', [('sphere','BraTS 2023 training, BraTS 2019/MSD testing.',10,'Sec. 4.2'),('c2p','Unseen datasets and unseen modalities, with explicit EM failure.',11,'Table 2'),('wcc4ms','Leave-one-domain-out evaluation across CT sources.',11,'Table 3'),('drift','Zero-shot real thick-slice MRI and unseen input thickness.',12,'Secs. 4.2–4.3')])
c('multimodal','Multimodal learning','Learn from different kinds of input or information. Here the term can refer to text/images or to heterogeneous medical imaging modalities.','C2P uses medical modalities and offline image–text distillation; Transferability studies understanding/generation in unified vision–language systems.', [('transferability','Unify image understanding and generation through shared or coupled models.',3,'Sec. 2.1'),('c2p','Separate modality-conditioned semantics from shared geometry.',5,'Sec. 2.2')])
c('transfer','Cross-task transfer','Train a capability in one task and test whether the same capability improves in another task without directly training that second task in the intervention.','Transfer varies with architecture, task, and direction; comparative evidence is not a universal causal law.', [('transferability','Counting, layout and text probes test understanding ↔ generation.',5,'Table 1; pp. 8–13')])
c('geometry','Geometry tokens','Learned tokens explicitly supervised with attributes derived from masks, such as area, bounding box and centroid.','The token prior can fail when the test structure has a topology unlike the training structures.', [('c2p','Guide dynamic segmentation and check inference-view self-consistency.',7,'Sec. 2.3; p. 8 Sec. 2.4')])
c('dynamic','Dynamic convolution','Generate convolution parameters conditioned on the current input instead of using one fixed output classifier for all inputs.','This describes input-specific weights, not training new weights at test time.', [('c2p','TGDH generates foreground/background weights from tokens and image context.',6,'Eq. 7')])
c('weak','Mixed / weak supervision','Combine dense voxel masks with less detailed labels, here bounding boxes. A box localizes an object without tracing its exact boundary.','Mixed supervision differs from unlabeled-data semi-supervision. More weak labels can hurt when domains or task weights are poorly balanced.', [('wcc4ms','Jointly exploit mask-labelled CT and box-only PN9.',9,'Sec. 4.2')])
c('dice','Dice / DSC','An overlap measure: twice the intersection divided by the total size of the two masks. Higher means stronger overlap.','Some papers report a fraction, others a percentage. Overlap alone can hide boundary mistakes.', [('sphere','Tumor-region Dice percentages.',14,'Table 7'),('c2p','Dataset and average segmentation Dice percentages.',9,'Table 1'),('wcc4ms','3D lesion DSC percentages.',9,'Table 1'),('pdf','Future-lesion DSC fractions.',12,'Table 1')])
c('hd95','HD95','The 95th-percentile boundary-distance metric used to assess segmentation boundary errors. Lower is better.','Do not confuse it with maximum Hausdorff distance (HD), which PDF reports. SPHERE’s printed Eq. 25 shows maxima despite its HD95 prose; follow the named table metric cautiously.', [('sphere','Reported Hausdorff95 tumor-boundary evaluation.',10,'Sec. 4.3; Table 8 p. 15'),('wcc4ms','Boundary metric alongside DSC.',9,'Sec. 4.2')])
c('psnr','PSNR','Peak signal-to-noise ratio expresses image reconstruction error relative to the intensity dynamic range, in decibels. Higher is better for this distortion measure.','High whole-image PSNR can coexist with poor prediction of a small changing lesion.', [('drift','Volumetric super-resolution fidelity.',10,'Evaluation'),('pdf','Whole-image future-scan similarity; compare with lesion metrics.',12,'Performance interpretation')])
c('ssim','SSIM','Structural similarity compares image luminance, contrast and structural information. Higher is better for this metric.','An image-quality score is not a validation of biological or clinical correctness.', [('drift','Average across slices in axial, coronal and sagittal directions.',10,'Evaluation'),('pdf','Image-level similarity for longitudinal forecasting.',21,'Appendix C.1')])
c('fid','FID / rFID / gFID','Compare image distributions using statistics of pretrained Inception features. Lower indicates closer feature distributions to the chosen reference.','The reference matters: Transferability compares against baseline-generated images; DeBaT distinguishes reconstruction and generation FID.', [('transferability','FID to the baseline generator measures distribution shift.',9,'Sec. 4.1'),('debat','rFID for reconstructed images and gFID for generated images.',7,'Sec. 3.1; p. 12 Table 2'),('paraflow','Generation-quality comparison at different solver settings.',5,'Table 1')])
(R/'data/concepts.json').write_text(json.dumps(concepts,ensure_ascii=False,indent=2)+'\n')
# Relationships are editorial comparisons of cited method roles, not claims that papers cite each other.
edges=[]
def edge(a,b,label,concept,reason,pa,ra,pb,rb):edges.append(dict(a=a,b=b,label=label,concept=concept,reason=reason,sources=[dict(paper=a,page=pa,label=ra),dict(paper=b,page=pb,label=rb)]))
edge('transferability','paraflow','Generative systems','diffusion','Both act on existing generators. Transferability changes task-specific training; ParaFlow changes numerical sampling with weights fixed.',3,'Sec. 2.1',4,'Algorithm 1')
edge('paraflow','drift','Efficient flow inference','flow','Both address iterative flow inference. ParaFlow parallelizes tentative steps; DRIFT trains residual transport and allocates sequential steps by thickness.',4,'Sec. 4',9,'Sec. 3.6')
edge('transferability','debat','Visual representations','latent','Representation choices affect what survives: shared encodings support task transfer; decoupled frequency codes preserve fine detail.',5,'Fig. 1',7,'Fig. 3')
edge('paraflow','pdf','Flow matching','flow','ParaFlow solves a pretrained generative trajectory; PDF learns two task-specific fields for disease progression.',3,'Sec. 4',8,'Sec. 3.2')
edge('drift','sphere','MRI acquisition priors','physics','DRIFT uses known thickness to condition reconstruction and schedule ODE steps. SPHERE estimates sampling parameters to construct a segmentation prior.',6,'Secs. 3.1–3.2',7,'Sec. 3.2')
edge('drift','pdf','Conditional MRI flows','flow','Both use flow learning and structurally meaningful image initialization. DRIFT restores resolution; PDF forecasts future disease and separates morphology from intensity.',7,'Secs. 3.3–3.4',9,'Inference')
edge('debat','wcc4ms','Haar wavelets · different roles','wavelets','DeBaT learns low/high latent representations. KernelWave modifies high-frequency coefficients to synthesize smooth/sharp training patches for segmentation.',8,'Sec. 3.2',6,'Sec. 3.2')
edge('pdf','sphere','Spatial deformation priors','dvf','PDF derives a warp from predicted lesion progression. SPHERE derives a structural proxy from simulated acquisition perturbations. Neither field has the same origin or purpose.',9,'Eq. 20',7,'Sec. 3.2')
edge('sphere','c2p','Medical segmentation','segmentation','Both add explicit structural information to segmentation. SPHERE uses an acquisition-related DVF; C2P uses geometry tokens and semantic concepts.',8,'Sec. 3.3',5,'Sec. 2.2')
edge('wcc4ms','c2p','Generalization across domains','generalization','WCC4MS handles mixed supervision and frequency shifts; C2P addresses multimodal conflicts with geometry/semantic tokens. Annotation and deployment assumptions differ.',11,'Table 3',11,'Table 2')
edge('sphere','wcc4ms','Acquisition-related robustness','generalization','Both tackle image-formation variation. SPHERE recovers MRI sampling parameters; WCC4MS simulates CT-like frequency shifts without estimating true reconstruction kernels.',7,'Sec. 3.2',14,'Mechanism validation')
edge('pdf','c2p','Explicit lesion geometry','geometry','PDF needs a baseline lesion mask to forecast evolution; C2P predicts masks and learned geometric attributes. Connecting them into a pipeline would be a new experiment, not a result of either paper.',9,'Inference',8,'Sec. 2.4')
(R/'data/relationships.json').write_text(json.dumps(edges,ensure_ascii=False,indent=2)+'\n')
